arguments.command:
cd /workspace/project && python3 - <<'EOF'
p='src/collector.c'
s=open(p).read()
old = """            for (uint64_t p = reverse ? hi - 1 : lo;
                 reverse ? p >= lo : p < hi;
                 reverse ? p-- : p++) {
                fill_payload(c, seed, p, rank);
                inject_data(c, rank, p, c->pbuf, NULL, 0);
            }"""
new = """            if (reverse) {
                for (uint64_t p = hi; p-- > lo;) {
                    fill_payload(c, seed, p, rank);
                    inject_data(c, rank, p, c->pbuf, NULL, 0);
                }
            } else {
                for (uint64_t p = lo; p < hi; p++) {
                    fill_payload(c, seed, p, rank);
                    inject_data(c, rank, p, c->pbuf, NULL, 0);
                }
            }"""
assert old in s
s = s.replace(old, new)
open(p,'w').write(s)
EOF
sed -n '/static void run_train/,/^}/p' src/collector.c
